<!doctype html><html lang="pl"><head><meta charset="utf-8"><title>{{ $invoice->number }}</title><style>body{font:14px Arial;max-width:800px;margin:40px auto;color:#172033}header{display:flex;justify-content:space-between;border-bottom:2px solid #063A60;padding-bottom:20px}table{width:100%;border-collapse:collapse;margin-top:30px}td,th{border-bottom:1px solid #ddd;padding:10px;text-align:left}.total{text-align:right;font-size:18px;margin-top:25px}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Drukuj / zapisz jako PDF</button><header><div><h1>FAKTURA VAT</h1><p>{{ $invoice->number }}</p></div><div><strong>CopyCabana</strong><br>ul. Bankowa 11<br>40-007 Katowice<br>biuro@copycabana.pl</div></header><h2>Nabywca</h2><p>{{ $invoice->buyer_name }}<br>{{ $invoice->buyer_company }}<br>NIP: {{ $invoice->buyer_nip ?: '—' }}<br>{{ collect($invoice->buyer_address)->filter()->implode(', ') }}</p><table><tr><th>Opis</th><th>Ilość</th><th>Wartość brutto</th></tr>@foreach($invoice->order->items as $item)<tr><td>{{ $item->product_name }}</td><td>{{ $item->quantity }}</td><td>{{ number_format((float)$item->total,2,',',' ') }} zł</td></tr>@endforeach</table><div class="total">Netto: {{ number_format((float)$invoice->net_total,2,',',' ') }} zł<br>VAT {{ $invoice->vat_rate }}%: {{ number_format((float)$invoice->vat_total,2,',',' ') }} zł<br><strong>Brutto: {{ number_format((float)$invoice->gross_total,2,',',' ') }} zł</strong></div></body></html>
